class Solution:
    def subsets(self, nums: list[int]) -> list[list[int]]:
        ans = []
        path = []

        def choose(start: int) -> None:
            ans.append(path[:])

            for i in range(start, len(nums)):
                path.append(nums[i])
                choose(i + 1)
                path.pop()

        choose(0)
        return ans
